def op(id,screen_id,title,business_id,status=CONFIRMED,req=None,src=None,dest=None,tab='該当なし',mode='読取り',dtab=None,dmode=None,roles=None,**kw):
    d=dict(id=id,transition_id=id.replace('OP-','TR-',1),screen_id=screen_id,destination_screen_id=dest or screen_id,title=title,business_id=business_id,status=status,requirements=req or [],source_ids=src or ['SRC-PAY'],origin_tab=tab,origin_mode=mode,destination_tab=dtab or tab,destination_mode=dmode or mode,control=('提案：'+title if status!=CURRENT else title),method='クリック／キーボード実行（具体部品は未入力）',roles=roles or BOTH,row_scope='給与班は全対象、局担当は自局記録と必要な共通基本情報。実効方式はPD-04。',visible='対象画面・タブ内。権限別の具体表示条件は未入力。',enabled='対象・権限・業務状態を検証した場合。物理方式は未入力。',preconditions='認証済みで対象レコードを識別できること。',validation='対象職員・対象履歴・操作権限の整合を確認。詳細検証値は未入力。',process='操作の業務条件に従う。具体的処理方式は未入力。',reads=['対象の論理レコード（正式物理名未入力）'],writes=[],retained='ログイン主体、選択対象、参照元の識別情報。',reset='明記のないリセット範囲は未決。',success='目的の状態と再表示を確認する。実装合格を意味しない。',failure='エラーを示し成功扱いしない。復旧・再実行の詳細は未決。',cancel='処理開始前の取消は状態を変更しない（画面操作案）。',unsaved='未保存入力の扱いは個別契約を優先。未定義の画面は未決。',acceptance=['対象・権限・業務状態と出力／保存結果が対応する。'],notes=[])
    if status==CURRENT:
        d['row_scope']='現行要件は同一所属制限。業務認可の実装・全経路検証は未完了。改修先の給与班全局／局担当自局と区別する。'
    elif d['roles']==PAY:
        d['row_scope']='給与班が担当業務について全対象職員を扱う。局担当者・本人にはこの操作を許可しない。実効方式はPD-04。'
        d['enabled']='給与班の実効権限、対象、業務状態を検証した場合。物理方式はPD-04。'
    elif d['roles']==LOCAL:
        d['row_scope']='局担当者の自局に属する業務記録。必要な共通職員基本情報だけを併用し、他局履歴を開示しない。実効方式はPD-04。'
    elif d['roles']==ADMIN:
        d['row_scope']='業務マスタ管理者の業務マスタ範囲。給与班との兼務は可能だが給与班またはシステム管理者だけでは許可しない。'
        d['enabled']='業務マスタ管理ロールを持ち、対象・有効期間・入力条件を検証した場合。'
    d.update(kw); ops.append(d)
