def validate():
    ids=lambda seq:{r['id'] for r in seq}
    sid,oid,srcid=ids(screens),ids(ops),ids(S)
    assert len(sid)==len(screens) and len(oid)==len(ops)
    assert len({o['transition_id'] for o in ops})==len(ops)
    allowed={CURRENT,CONFIRMED,PROPOSED,UNDECIDED}
    for item in S: assert (ROOT/item['path']).is_file(),item['path']
    for s in screens:
        assert s['status'] in allowed and set(s['source_ids'])<=srcid
    fields={'id','transition_id','screen_id','destination_screen_id','title','business_id','status','requirements','source_ids','origin_tab','origin_mode','destination_tab','destination_mode','control','method','roles','row_scope','visible','enabled','preconditions','validation','process','reads','writes','retained','reset','success','failure','cancel','unsaved','acceptance','notes'}
    arrays={'requirements','source_ids','roles','reads','writes','acceptance','notes'}
    for o in ops:
        assert set(o)==fields, (o['id'],set(o)^fields)
        assert o['screen_id'] in sid and o['destination_screen_id'] in sid
        assert o['status'] in allowed and set(o['source_ids'])<=srcid
        for k,v in o.items(): assert isinstance(v,list if k in arrays else str),(o['id'],k,type(v))
        assert len(o['title'])<=22,(o['id'],o['title'])
    for w in workflows:
        assert set(w['source_ids'])<=srcid and set(w['screen_ids'])<=sid
        stepids=ids(w['steps']); assert len(stepids)==len(w['steps'])
        assert any(s['kind']=='start' for s in w['steps']) and any(s['kind']=='end' for s in w['steps'])
        for s in w['steps']:
            assert s['screen_id'] in sid or s['screen_id']==''
            assert s['operation_id'] in oid or s['operation_id']==''
            assert s['kind'] in {'start','action','decision','external','end'}
            assert len(s['label'])<=22,(w['id'],s['label'])
        for e in w['edges']:
            assert e['from'] in stepids and e['to'] in stepids
            assert len(e['label'])<=22
    assert [s['tabs'] for s in screens if s['id']=='SCR-002'][0]==['基本情報','勤務条件','通勤','社会保険','税固定控除','給与簿']
    assert [s['tabs'] for s in screens if s['id']=='FUT-JLINK'][0]==['支給回の状況','出力','取込・照合']
    assert not any(o['screen_id']=='SCR-001' and o['destination_screen_id']=='SCR-005' for o in ops)
    assert {f'I{i}' for i in range(1,13)} <= set(sum([o['requirements'] for o in ops],[]))
if __name__=='__main__':
    validate()
    out=ROOT/'docs/review/pay-html-001/data/model.json'
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(json.dumps(model,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print(json.dumps(dict(path=str(out),screens=len(screens),operations=len(ops),workflows=len(workflows),sources=len(S),bytes=out.stat().st_size),ensure_ascii=False))
